.dcx section[aria-labelledby="int2-h"] ul.r-g4{ grid-template-columns: repeat(4, minmax(0, 1fr)) !important; }
@media (max-width: 640px){.dcx /* FAQ: the "+" stays on the question's row (the generic r-sbw rule would wrap it below long questions). */
      section[aria-labelledby="faq-h"] summary.r-sbw{ flex-wrap: nowrap !important; }
.dcx /* Integrations benefits: one left-aligned list instead of centred items with column dividers. */
      section[aria-labelledby="int2-h"] > div:nth-of-type(2){ padding: 0 24px !important; row-gap: 14px !important; }
.dcx section[aria-labelledby="int2-h"] > div:nth-of-type(2) > div{ flex: 1 1 100% !important; justify-content: flex-start !important; border-left: 0 !important; }
.dcx section[aria-labelledby="int2-h"] > div:nth-of-type(2) > div > div{ padding: 0 !important; }
.dcx /* Module stack calls-to-action: a compact label so long module names fit inside the pill. */
      section[aria-labelledby="stack-h"] article a[style*="height:52px"]{
        font-size: 14px !important; letter-spacing: .01em !important; line-height: 1.3 !important;
        gap: 14px !important; padding: 12px 22px !important; text-align: left !important;
      }
.dcx /* AI carousel cards: the product name and its badge share the narrow header. */
      section[aria-labelledby="ai-h"] article h3{ font-size: 17px !important; line-height: 1.25 !important; }
.dcx section[aria-labelledby="ai-h"] article{ padding: 20px !important; }
.dcx section[aria-labelledby="ai-h"] [aria-roledescription="carousel"] > div:last-child{ flex-wrap: nowrap !important; gap: 10px !important; }
}
@media (max-width: 860px){.dcx /* AI Receptionist phone sits centred under its photos once the columns stack. */
      section[aria-labelledby="rec-h"] [aria-live]{ margin: 0 auto !important; }
.dcx /* Outcome screenshot: the screenshot (always laid over the coded demo panels) becomes the frame's
         only content,.dcx so the image slot can size the frame to the whole picture. */
      section[aria-labelledby="o-h"] [role="img"] > div:nth-child(2){ padding: 0 !important; min-height: 0 !important; }
.dcx section[aria-labelledby="o-h"] [role="img"] > div:nth-child(2) > div[style*="position:absolute"]{ position: relative !important; inset: auto !important; height: 100% !important; }
.dcx section[aria-labelledby="o-h"] [role="img"] > div:nth-child(2) > div:not([style*="position:absolute"]){ display: none !important; }
}
